    printf("on leave\n");
}

void bunkClass(Student *s) {
    printf("Go out and play: \n");
}

int main() {
    Student sid;
    bunkClass(&sid);
    strcpy(sid.name, "Siddhartha Hazra");
    printf("%s\n", sid.name);
    return 0;
}


