2. Abstraction Abstraction is the process of concentrating on an object's or system's key features while disregarding unimportant elements. It enables programmers to produce models that simply and easily convey the core of real-world objects and ideas. We can achieve abstraction in two ways:Abstract Class: Abstract classes provide a way to create blueprints for objects without providing complete implementations. They serve as templates for other classes to inherit from, defining common behaviors and attributes that subclasses can extend and customize.Using Interface: Interfaces serve as blueprints for classes, defining a set of method signatures without specifying their implementations. Unlike classes, interfaces cannot contain instance fields but can include constants. They provide a way to achieve abstraction.AbstractionExample:
            C++

    #include <iostream>

// Abstract class
class Vehicle {
public:
    // Pure virtual functions
    virtual void accelerate() = 0;
    virtual void brake() = 0;

    // Concrete method
    void startEngine() {
        std::cout << "Engine started!" << std::endl;
    }
};

// Concrete class
class Car : public Vehicle {
public:
    void accelerate() override {
        std::cout << "Car: Pressing gas pedal..." << std::endl;
        // Hidden complex logic: fuel injection, gear shifting, etc.
    }

    void brake() override {
        std::cout << "Car: Applying brakes..." << std::endl;
        // Hidden logic: hydraulic pressure, brake pads, etc.
    }
};

int main() {
    Vehicle* myCar = new Car();
    myCar->startEngine();
    myCar->accelerate();
    myCar->brake();
    delete myCar;
    return 0;
}


            C

    #include <stdio.h>

// Abstract class equivalent using struct and function pointers
typedef struct {
    void (*accelerate)(struct Vehicle*);
    void (*brake)(struct Vehicle*);
    void (*startEngine)(struct Vehicle*);
} Vehicle;

// Concrete methods
void startEngine(Vehicle* self) {
    printf("Engine started!\n");
}

void carAccelerate(Vehicle* self) {
    printf("Car: Pressing gas pedal...\n");
    // Hidden complex logic: fuel injection, gear shifting, etc.
}

void carBrake(Vehicle* self) {
    printf("Car: Applying brakes...\n");
    // Hidden logic: hydraulic pressure, brake pads, etc.
}

int main() {
    Vehicle myCar = {
        .accelerate = carAccelerate,
        .brake = carBrake,
        .startEngine = startEngine
    };
    myCar.startEngine(&myCar);
    myCar.accelerate(&myCar);
    myCar.brake(&myCar);
    return 0;
}


            Java

    abstract class Vehicle {
    // Abstract methods (what it can do)
    abstract void accelerate();
    abstract void brake();

    // Concrete method (common to all vehicles)
    void startEngine() {
        System.out.println("Engine started!");
    }
}

// Concrete implementation (hidden details)
class Car extends Vehicle {
    @Override
    void accelerate() {
        System.out.println("Car: Pressing gas pedal...");
        // Hidden complex logic: fuel injection, gear shifting, etc.
    }

    @Override
    void brake() {
        System.out.println("Car: Applying brakes...");
        // Hidden logic: hydraulic pressure, brake pads, etc.
    }
}

public class Main {
    public static void main(String[] args) {
        Vehicle myCar = new Car();
        myCar.startEngine();  
        myCar.accelerate();   
        myCar.brake();        
    }
}


            Python

    from abc import ABC, abstractmethod

# Abstract class
class Vehicle(ABC):
    @abstractmethod
    def accelerate(self):
        pass

    @abstractmethod
    def brake(self):
        pass

    def startEngine(self):
        print("Engine started!")

# Concrete class
class Car(Vehicle):
    def accelerate(self):
        print("Car: Pressing gas pedal...")
        # Hidden complex logic: fuel injection, gear shifting, etc.

    def brake(self):
        print("Car: Applying brakes...")
        # Hidden logic: hydraulic pressure, brake pads, etc.

# Main execution
if __name__ == "__main__":
    myCar = Car()
    myCar.startEngine()
    myCar.accelerate()
    myCar.brake()


